<?php
namespace App\Http\Controllers;
use App\Models\{AccountMapping,Coa,Driver,DriverReceivable,Jurnal};
use App\Services\{AuditLogService,JournalService,PeriodLockService};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
class DriverReceivableController extends Controller {
 public function __construct(private JournalService $journals,private PeriodLockService $locks){}
 public function index(Request $r){$rows=DriverReceivable::with('driver')->where('origin','TRANSACTION')->when($r->filled('driver_id'),fn($q)=>$q->where('driver_id',(int)$r->input('driver_id')))->when($r->filled('search'),fn($q)=>$q->where(fn($x)=>$x->where('number','like','%'.$r->search.'%')->orWhere('reference','like','%'.$r->search.'%')->orWhere('vehicle_number','like','%'.$r->search.'%')->orWhere('description','like','%'.$r->search.'%')->orWhereHas('driver',fn($d)=>$d->where('code','like','%'.$r->search.'%')->orWhere('name','like','%'.$r->search.'%'))))->orderByDesc('date')->paginate(20)->withQueryString();$drivers=Driver::where('is_active',true)->orderBy('code')->get();return view('driver-receivables.index',compact('rows','drivers'));}
 public function show(DriverReceivable $driver_receivable){abort_unless($driver_receivable->origin==='TRANSACTION',404);$row=$driver_receivable->load(['driver','journal.items.coa','payments']);$journal=$row->journal;$receivableDebit=$journal?(float)$journal->items->where('coa_id',$row->receivable_coa_id)->sum('debit'):0.0;$journalChecks=['exists'=>(bool)$journal,'balanced'=>$journal?abs((float)$journal->total_debit-(float)$journal->total_kredit)<=0.01:false,'reference_matches'=>$journal?(string)$journal->referensi===(string)$row->number:false,'amount_matches'=>$journal?abs($receivableDebit-(float)$row->amount)<=0.01:false,'mapping_exists'=>(bool)$row->receivable_coa_id];$journalValid=$journalChecks['exists']&&$journalChecks['balanced']&&$journalChecks['reference_matches']&&$journalChecks['amount_matches'];return view('driver-receivables.show',compact('row','journal','journalChecks','journalValid'));}
 public function create(){return view('driver-receivables.form',$this->data());}
 public function store(Request $r){$v=$this->valid($r);if($this->locks->isLocked($v['date']))return back()->withInput()->with('error',$this->locks->lockedMessage($v['date']));DB::transaction(function()use($v){$driverLabel=$this->driverLabel((int)$v['driver_id']);$items=$this->items($v,$driverLabel);$j=$this->journals->createJournal($this->journals->generateJournalNumber('PS',$v['date']),$v['date'],'Piutang sopir '.$driverLabel.' - '.$v['number'],$items,$v['number'],auth()->id(),'Piutang Sopir','Jurnal Umum');$row=DriverReceivable::create($v+['origin'=>'TRANSACTION','paid'=>0,'balance'=>$v['amount'],'status'=>'OPEN','journal_id'=>$j->id,'created_by'=>auth()->id()]);app(AuditLogService::class)->record('create','driver-receivables',$row,'Membuat piutang sopir '.$row->number);});return redirect()->route('driver-receivables.index')->with('success','Piutang sopir dan jurnal berhasil dibuat.');}
 public function edit(DriverReceivable $driver_receivable){$this->guard($driver_receivable);return view('driver-receivables.form',$this->data()+['row'=>$driver_receivable]);}
 public function update(Request $r,DriverReceivable $driver_receivable){$this->guard($driver_receivable);$v=$this->valid($r,$driver_receivable);if($this->locks->isLocked($v['date']))return back()->withInput()->with('error',$this->locks->lockedMessage($v['date']));DB::transaction(function()use($v,$driver_receivable){$driverLabel=$this->driverLabel((int)$v['driver_id']);$row=DriverReceivable::whereKey($driver_receivable->id)->lockForUpdate()->firstOrFail();$this->guard($row);$j=Jurnal::whereKey($row->journal_id)->lockForUpdate()->firstOrFail();$no=$j->tanggal?->toDateString()===$v['date']?$j->no_jurnal:$this->journals->generateJournalNumber('PS',$v['date']);$j->update(['no_jurnal'=>$no,'tanggal'=>$v['date'],'keterangan'=>'Piutang sopir '.$driverLabel.' - '.$v['number'],'referensi'=>$v['number'],'total_debit'=>$v['amount'],'total_kredit'=>$v['amount']]);$j->items()->delete();$j->items()->createMany($this->items($v,$driverLabel));$row->update($v+['balance'=>$v['amount']]);app(AuditLogService::class)->record('update','driver-receivables',$row,'Mengubah piutang sopir '.$row->number);});return redirect()->route('driver-receivables.index')->with('success','Piutang sopir dan jurnal berhasil diperbarui.');}
 public function destroy(DriverReceivable $driver_receivable){$this->guard($driver_receivable);DB::transaction(function()use($driver_receivable){$row=DriverReceivable::whereKey($driver_receivable->id)->lockForUpdate()->firstOrFail();$this->guard($row);$j=Jurnal::whereKey($row->journal_id)->lockForUpdate()->firstOrFail();$j->items()->delete();$row->delete();$j->delete();});return back()->with('success','Piutang sopir dan jurnal berhasil dihapus.');}
 private function data(){return ['drivers'=>Driver::where('is_active',true)->orderBy('code')->get(),'accounts'=>Coa::active()->posting()->orderBy('kode_akun')->get(),'receivableId'=>AccountMapping::getCoaId('driver_receivable')];}
 private function valid(Request $r,?DriverReceivable $row=null):array{return $r->validate(['number'=>['required','string','max:40',Rule::unique('driver_receivables')->ignore($row?->id)],'date'=>['required','date'],'due_date'=>['nullable','date','after_or_equal:date'],'driver_id'=>['required','exists:drivers,id'],'type'=>['required',Rule::in(['KERUSAKAN_KENDARAAN','KAS_BON','KEHILANGAN_BARANG','TILANG','SELISIH_SETORAN','LAINNYA'])],'vehicle_number'=>['nullable','string','max:30'],'reference'=>['nullable','string','max:100'],'amount'=>['required','numeric','gt:0'],'description'=>['required','string','max:1000'],'receivable_coa_id'=>['required','exists:coas,id'],'counter_coa_id'=>['required','different:receivable_coa_id','exists:coas,id']]);}
 private function items(array $v,string $driverLabel){return [['coa_id'=>$v['receivable_coa_id'],'debit'=>$v['amount'],'kredit'=>0,'deskripsi'=>'Piutang sopir '.$driverLabel.' (No: '.$v['number'].')'],['coa_id'=>$v['counter_coa_id'],'debit'=>0,'kredit'=>$v['amount'],'deskripsi'=>$v['description'].' - '.$driverLabel]];}
 private function guard(DriverReceivable $r){abort_unless($r->origin==='TRANSACTION',404);if((float)$r->paid>0||$r->payments()->where('status','POSTED')->exists())abort(422,'Piutang yang sudah dibayar tidak dapat diubah atau dihapus.');if($this->locks->isLocked($r->date))abort(422,$this->locks->lockedMessage($r->date));}
 private function driverLabel(int $driverId):string{$driver=Driver::find($driverId);if(!$driver)return 'Sopir #'.$driverId;$label=trim(($driver->code ?? '').' - '.($driver->name ?? ''),' -');return $label!==''?$label:'Sopir #'.$driverId;}
}
